insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('daunk-deina-schmiaraasch-haumas-no-gwuuna', 'Daunk deina Schmiaraasch haumas no gwuuna!', '', '', '', 'Wiener Kartentipplerjargon', 'Dank deiner Schmierage haben wir''s noch gewonnen!', '[{"kategorie": "wörtlich", "text": "\"Dank der hohen Karten, mit denen du meine Stiche aufgefettet hast, haben wir das Spiel noch gewonnen!\"  2. Gut geschmiert, Alter – das hat uns den Sieg gebracht!  3. Die Punkte, die du reingebuttert hast, haben uns rausgerissen!"}]'::jsonb, ''),
  ('daunk-deina-schmiia-haumas-no-gwuuna', 'Daunk deina Schmiia haumas no gwuuna!', '', '', '', 'Wiener Kartentipplerjargon', 'Dank deiner Schmier haben wir''s noch gewonnen!', '[{"kategorie": "wörtlich", "text": "\"Dank der hohen Karten, mit denen du meine Stiche aufgefettet hast, haben wir das Spiel noch gewonnen!\"  2. Gut geschmiert, Alter – das hat uns den Sieg gebracht!  3. Die Punkte, die du reingebuttert hast, haben uns rausgerissen!"}]'::jsonb, ''),
  ('dei-schmiiraasch-kaunn-kaana-leesn', 'Dei Schmiiraasch kaunn kaana leesn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deine Schmirage kann keiner lesen!', '[{"kategorie": "wörtlich", "text": "Dein Gekritzel kann keiner lesen!  2. Deine Sauklaue ist total unleserlich!  3. Deine Hieroglyphen kann niemand entziffern!"}]'::jsonb, ''),
  ('schmiaralien-geegn-schweign-und-schoo-is-a-schdueue-wiara-groob', 'Schmiaralien geegn Schweign - und schoo is a schdüü wiara Groob!', '', '', '', 'Wiener Gaunersprache', 'Schmiralien gegen Schweigen - und schon ist er still wie ein Grab!', '[{"kategorie": "wörtlich", "text": "\"Schmiergeld gegen Schweigen - und schon ist er still wie ein Grab!\"  2. Ein bisschen Schweigegeld – und der Typ klappt zu wie ein Sargdeckel!  3. Ein bisschen Bestechung – und er schweigt wie ein Mönch in der Fastenzeit!"}]'::jsonb, ''),
  ('schmiaralien-auneema', 'Schmiaralien auneema', '', '', '', 'Wiener Gaunersprache', 'Schmieralien annehmen', '[{"kategorie": "wörtlich", "text": "\"Schmiergeld annehmen\""}, {"kategorie": "", "text": "Bestechungsgeld annehmen"}, {"kategorie": "", "text": "Geld unter der Hand nehmen"}, {"kategorie": "", "text": "sich schmieren lassen"}]'::jsonb, 'Wea Schmiaralien aunimmd, taunzd noch unsara Pfeifn!'),
  ('wea-schmiaralien-aunimmd-taunzd-noch-unsara-pfeifn', 'Wea Schmiaralien aunimmd, taunzd noch unsara Pfeifn!', '', '', '', 'Wiener Gaunersprache', 'Wer Schmieralien annimmt, tanzt nach unserer Pfeife!', '[{"kategorie": "wörtlich", "text": "\"Wer Schmiergeld annimmt, tanzt nach unserer Pfeife!\"  2. Wer sich schmieren lässt, hört auf unser Kommando!  3. Wer Schmiergeld annimmt, muss Männchen machen, wenn wir pfeifen!"}]'::jsonb, 'Schmiaralien auneema'),
  ('da-schmiaranski-aus-unsan-buero-hod-wieda-zuagschloong-den-sei-schrift-kaunn-nuara-kryptolog-entziffan', 'Da Schmiaranski aus unsan Büro hod wieda zuagschloong - den sei Schrift kaunn  nuara Kryptolog entziffan!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Schmieranski aus unserem Büro hat wieder zugeschlagen - seine Schrift kann nur ein Kryptologe entziffern!', '[{"kategorie": "wörtlich", "text": "\"Der Schmierheini aus unserem Büro hat wieder zugeschlagen - entziffern kann seine Schrift nur ein Kryptologe!\"  2. Der Sauklauenkönig vom Büro war wieder am Werk – entziffern kann’s nur der Geheimdienst!  3. Wir nennen ihn intern den ''Hieroglyphen-Heini'' - keine Sau kann seine Schrift lesen!"}]'::jsonb, ''),
  ('waunn-dea-schmiaranski-wos-schreibd-kaunnsda-sicha-sei-dreiviadl-san-frei-eafundn-und-da-rest-is-foisch-zitiad', 'Waunn dea Schmiaranski wos schreibd, kaunnsda sicha sei: Dreiviadl san frei eafundn, und da Rest is foisch zitiad!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wenn der Schmieranski was schreibt, kannst du dir sicher sein: Dreiviertel sind frei erfunden, und der Rest ist falsch zitiert!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieser Schmierfink was schreibt, kannst du dir sicher sein: Dreiviertel ist erfunden, der Rest falsch zitiert!\"  2. Wenn dieser Klatschreporter den Stift schwingt, dann weißt du: Dreiviertel ist erfunden, der Rest falsch zitiert!  3. Wenn der Schmieranski was raushaut, ist’s meistens frei erfunden – und das bisschen Wahrheit, das noch bleibt, verdreht er dann auch noch!"}]'::jsonb, ''),
  ('iwaroi-im-buero-liing-schmiiablaadln-umanaund-kaa-wunda-dass-i-nix-find', 'Iwaroi im Büro liing Schmiiablaadln umanaund - kaa Wunda, dass I nix find!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Überall im Büro liegen Schmierblätter rum – kein Wunder, dass ich nix mehr finde!', '[{"kategorie": "wörtlich", "text": "\"Überall im Büro liegen Schmierzettel rum – kein Wunder, dass ich nix mehr finde!\"  2. Im ganzen Büro liegen lose Zettel verstreut – da ist es kein Wunder, dass ich nichts finde!  3. Das ganze Büro ist voll mit Notizzetteln - kein Wunder, dass ich den Überblick verliere!"}]'::jsonb, ''),
  ('mei-nochba-dea-trottl-glaubd-ollas-wos-in-de-schmiiablaadln-schdeed', 'Mei Nochba, dea Trottl, glaubd ollas, wos in de Schmiiablaadln schdeed!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein Nachbar, der Trottel, glaubt alles, was in den Schmierblattln steht!', '[{"kategorie": "wörtlich", "text": "\"Mein Nachbar, dieser Depp, glaubt alles, was in den Schmierblättern steht!\"  2. Mein Nachbar, dieser Dolm,  lässt sich vom Revolverblättern mehr beeinflussen als von seinem Hirn!  3. Mein Nachbar ist die wandelnde Schlagzeile – jeden Tag erzählt mir der Dillo von einem neuen Weltuntergang, über den sein Klatschblatt grad wieder berichtet!"}]'::jsonb, ''),
  ('i-hob-a-ostreins-schmiiablaadl-ghobd-lauta-hooche-foam-owa-ka-aanzige-tarock', 'I hob a ostreins Schmiiablaadl ghobd - lauta hooche Foam, owa ka aanzige Tarock!', '', '', '', 'Wiener Kartentipplerjargon', 'Ich hab ein astreines Schmierblatt gehabt – lauter hohe Farben, aber keine einzige Tarock!', '[{"kategorie": "wörtlich", "text": "\"Ich hab ein astreines Schmierblatt gehabt – lauter hohe Farbkarten, aber keine einzige Tarock!\"  2. Ich hatte ein richtig fettes Schmierblatt – keine einzige Tarock, dafür aber fette Farbkarten zum Schmieren!  3. Ich hatte keine einzige Tarock in der Hand - aber schmiertechnisch war beim Blatt echt wertvoll!"}]'::jsonb, ''),
  ('mei-muada-leesd-nua-no-des-aane-rewoiwablaadl-mit-dea-brauchsd-goa-ned-easchd-diskutian', 'Mei Muada leesd nua no des aane Rewoiwablaadl - mit dea brauchsd goa ned easchd diskutian!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Meine Mutter liest nur noch dieses eine Revolverblattl – mit der brauchst du gar nicht erst diskutieren!', '[{"kategorie": "wörtlich", "text": "\"Meine Mutter liest nur noch dieses eine Revolverblatt – diskutieren bringt da nix!\"  2. Seit meine Mutter nur noch dieses eine Klatschblatt verschlingt, ist jede Diskussion mit ihr zwecklos!  3. Meine Mutter frisst das Schmierblattl mit Haut und Haar – reden ist da verlorene Zeit!"}]'::jsonb, ''),
  ('nix-wos-in-dem-drecksblaadl-schdeed-is-woa-owa-de-leit-fressen-s-trotzdem', 'Nix, wos in dem Drecksblaadl schdeed, is woa - owa de Leit fressen''s trotzdem!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Nichts, was in diesem Drecksblatt steht, ist wahr – aber die Leute fressen es trotzdem!', '[{"kategorie": "wörtlich", "text": "\"In diesem Drecksblatt steht doch nur gelogenes Zeug – und die Leute fressen es auch noch!\"  2. In diesem Schmierblatt steht nur erfundener Unsinn drin – aber die Leute schlucken’s wie warme Semmeln!  3. Dieses Revolverblatt ist voll mit Lügen und Übertreibungen – aber die Leute glauben’s trotzdem!"}]'::jsonb, ''),
  ('wos-eawoadsd-da-von-so-an-kaasblaadl-sicha-kaa-rescheasch-sondan-nua-knollige-schlogzaeun', 'Wos eawoadsd da von so an Kaasblaadl - sicha kaa Rescheasch, sondan nua knollige Schlogzäun!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Was erwartest du dir von so einem Käseblattl - sicher keine Recherche, sondern nur knallige Schlagzeilen!', '[{"kategorie": "wörtlich", "text": "\"Von dem Käseblatt brauchst du dir keine seriöse Recherche erwarten, sondern vielmehr knallige Schlagzeilen!\"  2. Ach komm, als ob dieses Schmierblatt irgendwas recherchieren würde – das Einzige, was die prüfen, ist die Schriftgröße der Schlagzeile!  3. Von dem Drecksblatt brauchst du dir keine echten Infos erwarten – vielmehr Aufregung in Großbuchstaben!"}]'::jsonb, ''),
  ('dea-schmiiad-fia-des-rewoiwablaadl-nix-ois-gift-aufs-papier-egal-wen-s-triffd', 'Dea schmiiad fia des Rewoiwablaadl nix ois Gift aufs Papier – egal, wen''s triffd!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der schmiert für dieses Revolverblatt nichts als Gift aufs Papier - egal, wen''s trifft!', '[{"kategorie": "wörtlich", "text": "\"Was der in diesem Revolverblatt an Skandaltexten verfasst, ist pures Gift - ohne Rücksicht auf die Person!\"  2. Er verteilt in seinem Schmierblatt verbale Brandbomben fürs Boulevard – treffsicher und völlig skrupellos!  3. Dieser Schmieranski textet für sein Schundblatt nichts als Skandalmüll  - Hauptsache, es haut so richtig rein!"}]'::jsonb, ''),
  ('du-muassd-bei-da-maschin-de-looga-schmiian', 'Du muassd bei da Maschin de Looga schmiian!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Du musst bei der Maschine die Lager schmieren!', '[{"kategorie": "", "text": "Du musst die Lager der Maschine ölen!  2. Du solltest die Lager der Maschine einfetten!  3. Denk daran, die Lager der Maschine zu schmieren!"}]'::jsonb, ''),
  ('wos-du-do-zsaummschmiiasd-kaunn-kaana-leesn', 'Wos du do zsaummschmiiasd, kaunn kaana leesn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was du da zusammenschmierst, kann keiner lesen!', '[{"kategorie": "wörtlich", "text": "\"Was du da zusammenkritzelst, kann keiner entziffern!\"  2. Deine Sauklaue kann niemand lesen!  3. Dein Gekritzel ist zur Gänze unleserlich!"}]'::jsonb, ''),
  ('beaumte-muass-ma-schmiian-sunst-beweengs-eanan-oasch-nii', 'Beaumte muass ma schmiian, sunst beweengs eanan Oasch nii!', '', '', '', 'Wiener Gaunersprache', 'Beamte muss man schmieren, sonst bewegen sie ihren Arsch nie!', '[{"kategorie": "", "text": "Beamte muss man ölen, sonst geht gar nichts weiter!  2. Ohne Schmiergeld rührt sich bei Beamten gar nichts!  3. Beamte muss man bestechen, sonst bewegen Sie ihren Arsch nie!"}]'::jsonb, ''),
  ('wem-aane-schmiian', 'wem aane schmiian', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine schmieren', '[{"kategorie": "wörtlich", "text": "\"jemandem eine Ohrfeige verpassen\""}, {"kategorie": "", "text": "jemanden ohrfeigen, [[abwatschen]], [[abfotzen]], [[abflaschen]], [[dögeln]]"}, {"kategorie": "", "text": "jemandem eine [[tuschen]], [[picken]], [[flacken]], [[antauchen]][[schnalzen]], [[paschen]], [[wassern]]"}]'::jsonb, 'Waunn dea no amoi so bleed grinsd, schmiiar I eam aane, dass eams Lochn eigfriad!'),
  ('waunn-dea-no-amoi-so-bleed-grinsd-schmiiar-i-eam-aane-dass-eams-lochn-eigfriad', 'Waunn dea no amoi so bleed grinsd, schmiiar I eam aane, dass eams Lochn eigfriad!', '', '', '', 'Wiener Gaunersprache', 'Wenn der noch einmal so blöd grinst, schmier ich ihm eine, dass ihm das Lachen einfriert!', '[{"kategorie": "wörtlich", "text": "\"Wenn der noch einmal so blöd grinst, hau ich ihm eine in die Fresse, auf dass ihm sein Lächeln einfriert!\"  2. Wenn der noch einmal so dämlich grinst, kriegt er eine geballert, dass er sein Gebiss zusammensuchen kann!  3. Noch so ein dummes Grinsen – und der frisst fünf Finger frontal!"}]'::jsonb, 'wem aane schmiian'),
  ('an-schmiiakaas-kaunnst-haum', 'An Schmiiakaas kaunnst haum!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einen Schmierkas kannst haben', '[{"kategorie": "wörtlich", "text": "\"Einen Schmierkäse kannst du haben!\"  2. (fig.) Träum weiter – von mir gibt’s nichts!  3. Du bekommst von mir genau gar nichts – keinen Cent!  4. Einen feuchten Dreck bekommst du!"}]'::jsonb, ''),
  ('a-schmiisal-untan-aunzug-is-fia-mi-pflicht', 'A Schmiisal untan Aunzug is fia mi Pflicht!', '', '', '', '', 'Ein Schmieserl unter dem Anzug ist für mich Pflicht!', '[{"kategorie": "", "text": "Ein Hemdeinsatz unter dem Anzug ist für mich unerlässlich!  2. Ohne Hemdeinsatz unter dem Anzug geht es für mich nicht!  3. Unter dem Anzug trage ich immer einen Hemdeinsatz, das ist ein Muss für mich!"}]'::jsonb, ''),
  ('a-schmiisl-untan-aunzug-is-fia-mi-pflicht', 'A Schmiisl untan Aunzug is fia mi Pflicht!', '', '', '', '', 'Ein Schmiesel unter dem Anzug ist für mich Pflicht!', '[{"kategorie": "", "text": "Ein Hemdeinsatz unter dem Anzug ist für mich unerlässlich!  2. Ohne Hemdeinsatz unter dem Anzug geht es für mich nicht!  3. Unter dem Anzug trage ich immer einen Hemdeinsatz, das ist ein Muss für mich!"}]'::jsonb, ''),
  ('a-schmiisettl-untan-aunzug-is-fia-mi-pflicht', 'A Schmiisettl untan Aunzug is fia mi Pflicht!', '', '', '', '', 'Ein Schmiesettl unter dem Anzug ist für mich Pflicht!', '[{"kategorie": "", "text": "Ein Hemdeinsatz unter dem Anzug ist für mich unerlässlich!  2. Ohne Hemdeinsatz unter dem Anzug geht es für mich nicht!  3. Unter dem Anzug trage ich immer einen Hemdeinsatz, das ist ein Muss für mich!"}]'::jsonb, ''),
  ('vuam-lackian-gheads-hoiz-gscheid-gschmiagld', 'Vuam Lackian gheads Hoiz gscheid gschmiagld!', '', '', '', '', 'Vor dem Lackieren gehört das Holz gründlich geschmirgelt!', '[{"kategorie": "", "text": "Vor dem Lackieren muss das Holz sorgfältig abgeschliffen werden!  2. Bevor man lackiert, sollte das Holz gründlich geglättet sein!  3. Vor dem Anstrich muss das Holz gründlich abgeschmirgelt werden!"}]'::jsonb, ''),
  ('do-schmiaklds-wiarin-ana-braadlbroodahittn', 'Do schmiaklds wiarin ana Braadlbroodahittn!', '', '', '', '', 'Da schmirkelt''s wie in einer Bratenbräterhütte!', '[{"kategorie": "wörtlich", "text": "\"Da stinkt es nach altem Fett wie in einer miefigen Bratstube! \"  2. Da stinkt es nach ranzigem Fett wie in einer alten Garküche!  3. Da riecht es wie in einer alten Frittenbude!"}]'::jsonb, ''),
  ('iss-aa-de-rindn-und-ned-ollawaeu-nua-de-schmoin', 'Iss aa de Rindn und ned ollawäu nua de Schmoin!', '', '', '', '', 'Iss auch die Rinde und nicht alleweil nur die Schmolle!', '[{"kategorie": "", "text": "Iss auch die Rinde und nicht immer nur das Weiche vom Brot!  2. Iss auch die Kruste, nicht nur die weiche Mitte!  3. Lass die Rinde nicht liegen, iss das ganze Brot!"}]'::jsonb, ''),
  ('i-hob-ka-zeit-fia-so-an-schmonzes', 'I hob ka Zeit fia so an Schmonzes!', '', '', '', '', 'Ich habe keine Zeit für so einen Schmonzes!', '[{"kategorie": "wörtlich", "text": "\"Ich habe keine Zeit für solchen Unsinn!\"  2. Ich habe keine Zeit für so einen [[Firlefanz]]!  3. Ich habe keine Zeit für so einen [[Schmarren]]!"}]'::jsonb, ''),
  ('schau-doch-ned-so-an-schmonzes', 'Schau doch ned so an Schmonzes!', '', '', '', '', 'Schau doch nicht so einen Schmonzes!', '[{"kategorie": "", "text": "Schau dir doch nicht so einen [[Schmarren]] an!  2. Schau dir doch nicht so einen Kitsch an!  3. Gib dir doch nicht so einen [[Schmachtfetzen]]! (rührseliges, dramatisch wertloses Stück)"}]'::jsonb, ''),
  ('red-doch-ned-so-an-schmonzes', 'Red doch ned so an Schmonzes!', '', '', '', '', 'Rede doch nicht so einen Schmonzes!', '[{"kategorie": "", "text": "Rede doch nicht so einen [[Schmarren]] daher!  2. Rede doch nicht solch einen Blödsinn!  3. [[Red]] ned so an Schas!"}]'::jsonb, ''),
  ('wos-fiara-kitschige-schmonzettn', 'Wos fiara kitschige Schmonzettn!', '', '', '', '', 'Was für eine kitschige Schmonzette!', '[{"kategorie": "", "text": "Was für ein kitschiges Machwerk!  2. Was für ein rührseliger Kitsch!  3. Was für ein schnulziger [[Schmachtfetzen]]!  4. Was für ein schmalziger [[Schinken]]!"}]'::jsonb, ''),
  ('a-schmutzal-fias-mutzal', 'A Schmutzal fias Mutzal!', '', '', '', '', 'Ein Schmutzerl fürs Mutzerl!', '[{"kategorie": "wörtlich", "text": "\"Ein Häppchen fürs Kätzchen!\"  2. Ein Leckerchen fürs Miezekätzchen!  3. Eine kleine Belohnung fürs Samtpfötchen!"}]'::jsonb, ''),
  ('oida-bist-lost-oda-aafoch-nua-schbasti', 'Oida, bist lost oda aafoch nua Schbasti?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Alter, bist du lost oder einfach nur Spasti?', '[{"kategorie": "wörtlich", "text": "\"Alter, bist du geistig abwesend oder einfach nur Spastiker?\"  2. Alter, hast du einen an der Waffel oder bist du einfach nur spastisch?  3. Mann, bist du auf Sendepause oder einfach nur retarded?"}]'::jsonb, ''),
  ('moch-kaan-auf-kuul-du-schbacko-es-nimmd-di-sowiiso-kaana-eanst', 'Moch kaan auf kuul, du Schbacko - es nimmd di sowiiso kaana eanst!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mach keinen auf cool, du Spacko – es nimmt dich sowieso keiner ernst!', '[{"kategorie": "wörtlich", "text": "\"Mach keinen auf cool, du Nullchecker – es nimmt dich ohnehin keiner ernst!\"  2. Mach mal halblang, du Witzfigur – du bist nicht so cool, wie du denkst!  3. Hör auf, den dicken Macker zu machen, du Flachpfeife – keiner kauft dir das ab!"}]'::jsonb, ''),
  ('l-m-a', 'L.M.A.', '', '', '', '', 'L.M.A.', '[{"kategorie": "wörtlich, verhüllende Abkürzung für", "text": "\"Leck mich am Arsch!\"  2. Du kannst mich mal!  3. Du kannst mich mal kreuzweise!  4. [[Mischimorschi]]!"}]'::jsonb, 'Leck mi auf Krakau!'),
  ('l-m-a-a', 'L.M.A.A.', '', '', '', '', 'L.M.A.A.', '[{"kategorie": "verhüllende Abkürzung für", "text": "\"Leck mich am Arsch!\"  2. Du kannst mich mal!  3. Du kannst mich mal kreuzweise!  [[Mischimorschi]]!"}]'::jsonb, ''),
  ('wos-schnoowaesd-do-umanaund', 'Wos schnoowäsd do umanaund?', '', '', '', '', 'Was schnabelst du da herum?', '[{"kategorie": "", "text": "Was faselst du da?  2. Was redest du da für einen Quatsch?  3. Worüber lässt du dich da gerade aus?"}]'::jsonb, ''),
  ('gemma-a-schmutzal-schnabulian', 'Gemma a Schmutzal schnabulian!', '', '', '', '', 'Gehen wir ein Schmutzerl schnabulieren!', '[{"kategorie": "", "text": "Lasst uns ein Häppchen essen gehen!  2. Lasst uns eine Kleinigkeit futtern gehen!  3. [[Hau ma uns a Schmutzal zwischn de Beissa!]]"}]'::jsonb, ''),
  ('hau-ma-uns-a-schmutzal-zwischn-de-beissa', 'Hau ma uns a Schmutzal zwischn de Beissa!', '', '', '', '', 'Hauen wir uns ein Schmutzerl zwischen die Beißer!', '[{"kategorie": "scherzhaft für", "text": "Lasst uns eine Kleinigkeit futtern gehen!  2. Lasst uns ein Häppchen schnabulieren gehen!  3. [[Gemma]] a Schmutzal schnabulian!"}]'::jsonb, 'Gemma a Schmutzal schnabulian!'),
  ('wems-schmeckd-dea-schnabuliad-ollas-zsaumm', 'Wems schmeckd, dea schnabuliad ollas zsaumm!', '', '', '', '', 'Wem es schmeckt, der schnabuliert alles zusammen!', '[{"kategorie": "wörtlich", "text": "\"Wem es mundet, der isst alles auf!\"  2. Wer es lecker findet, der futtert alles auf!  3. Wem es schmeckt, der putzt alles auf!"}]'::jsonb, ''),
  ('jetza-schnacklds', 'Jetza schnacklds!', '', '', '', '', 'Jetzt schnackelt''s!', '[{"kategorie": "wörtlich", "text": "\"Jetzt schnackelt es!\"  2. Jetzt klappt es plötzlich!  3. Jetzt funktioniert es auf einmal!  4. [[Pfeift]] schon!"}]'::jsonb, ''),
  ('mia-schnackln-de-knia', 'Mia schnackln de Knia!', '', '', '', '', 'Mir schnackeln die Knie!', '[{"kategorie": "", "text": "Mir schlottern die Knie!  2. Mir zittern die Knie!"}]'::jsonb, ''),
  ('es-hod-bei-eam-gschnackld', 'Es hod bei eam gschnackld!', '', '', '', '', 'Es hat bei ihm geschnackelt!', '[{"kategorie": "wörtlich", "text": "\"Es hat bei ihm geschnalzt!\"  2. (scherzhaft für):  Es hat bei ihm klick gemacht!  3. Der Groschen ist bei ihm gefallen!  4. Er hat''s endlich kapiert!  5. (fig.) Er hat sich Hals über Kopf verliebt!  6. Er ist hin und weg!  7. Er hat sich bis über beide Ohren verliebt!  8. Er ist total verknallt!"}]'::jsonb, ''),
  ('es-geed-eam-dauand-de-schnodan', 'Es geed eam dauand de Schnodan!', '', '', '', '', 'Es geht ihm dauernd die Schnadern!', '[{"kategorie": "", "text": "Er ist ununterbrochen am Reden!  2. Sein Mundwerk geht in einer Tour!"}]'::jsonb, ''),
  ('jetzd-hodas-endlich-gschnoind', 'Jetzd hodas endlich gschnoind!', '', '', '', '', 'Jetzt hat er es endlich geschnallt!', '[{"kategorie": "", "text": "Jetzt hat er es endlich kapiert!  2. Jetzt hat er es endlich begriffen!"}]'::jsonb, ''),
  ('aum-schdaummtisch-wiad-heit-wieda-fleissig-gschnapsld', 'Aum Schdaummtisch wiad heit wieda fleissig gschnapsld!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Am Stammtisch wird heut wieder fleißig geschnapselt!', '[{"kategorie": "wörtlich", "text": "\"Am Stammtisch wird heute wieder reichlich Schnaps getrunken!\"  2. Heute wird am Stammtisch wieder ein Stamperl nach dem anderen gekippt!  3. Bei uns am Stammtisch fließt der Schnaps heute wieder in Strömen!"}]'::jsonb, ''),
  ('a-guada-schnops-nochn-essn-hueuefd-bei-da-vadauung', 'A guada Schnops nochn Essn hüüfd bei da Vadauung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein guter Schnaps nach dem Essen hilft bei der Verdauung!', '[{"kategorie": "wörtlich", "text": "\"Ein gutes [[Stamperl]] nach dem Essen regt die Verdauung an!\"  2. Der Schnaps nach’m Essen ist quasi ärztlich verordnet – von der Wirtin!  3. Das Fett muss runter – und der Schnaps ist der Lift!"}]'::jsonb, ''),
  ('a-schnapsal-noochn-essn-und-des-braadl-is-vagessn', 'A Schnapsal noochn Essn, und des Braadl is vagessn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Schnapserl nach dem Essen, und das Bratl ist vergessen!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Ein Schnäpschen nach dem Essen, und der Braten ist vergessen!\"  2. Ein Klarer nach dem Schmaus, und das Völlegefühl geht raus!  3. EinStamperl braucht''s dann ganz am Schluss – weil der Braten sitzen muss!"}]'::jsonb, ''),
  ('a-gscheids-schnapsal-noochn-essn-und-da-moong-lochd', 'A gscheids Schnapsal noochn Essn - und da Moong lochd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein gescheites Schnapserl nach dem Essen - und der Magen lacht!', '[{"kategorie": "wörtlich", "text": "\"Ein ordentliches Verdauungsschnäpschen nach dem Essen – das tut dem Magen gut!\"  2. Nach’m Essn braucht’s ein Stamperl – dann sagt der Magen ''Danke schön''!\"  3. (Scherzreim): \"Ein Kurzer nach dem Essen – und der Schweinsbraten ist vergessen!\""}]'::jsonb, ''),
  ('a-vadauungsschnapsal-is-bessa-ois-jeeda-kreitatee', 'A Vadauungsschnapsal is bessa ois jeeda Kreitatee!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Verdauungsschnapserl ist besser als jeder Kräutertee!', '[{"kategorie": "wörtlich", "text": "\"Ein Verdauungsschnäpschen ist besser als jeder Kräutertee!\"  2. Ein Digestif hilft mehr als ein Häferl heißes Wasser mit Unkraut drin!  3. Tee streichelt – Schnaps überzeugt!"}]'::jsonb, ''),
