  ('ausn-schneida-sei', 'ausn Schneida sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'aus dem Schneider sein', '[{"kategorie": "wörtlich", "text": "\"aus der Gefahrenzone sein\""}, {"kategorie": "", "text": "aus dem Gröbsten raus sein"}, {"kategorie": "", "text": "die kritische Phase hinter sich haben"}, {"kategorie": "Kartenspielerjargon", "text": "\"über der kritischen Punktemarke sein\", \"die Mindestpunkteanzahl erreicht haben\", [[ausn Wossa sei]] (beim [[Schnapsen]] wenigstens einen Punkt angeschrieben haben)"}, {"kategorie": "fig.", "text": "seine Schäfchen im Trockenen haben, für immer ausgesorgt haben, keine Geldsorgen mehr haben"}]'::jsonb, 'Mit dem Schdich bin I endlich ausn Schneida!'),
  ('mit-dem-schdich-bin-i-endlich-ausn-schneida', 'Mit dem Schdich bin I endlich ausn Schneida!', '', '', '', 'Wiener Kartentipplerjargon', 'Mit diesem Stich bin ich endlich aus dem Schneider!', '[{"kategorie": "wörtlich", "text": "\"Dieser Stich bringt mich endgültig über die kritische Punktemarke!\"  2. Mit diesem Stich habe ich endgültig mehr als das Punkteminimum!  3. Der eine Stich hat’s gebracht – unter’m Strich bin ich jetzt raus!"}]'::jsonb, 'ausn Schneida sei'),
