  ('iwad-schnua-haun', 'iwad Schnua haun', '', '', '', '', 'über die Schnur hauen', '[{"kategorie": "wörtlich", "text": "\"über die Stränge schlagen\""}, {"kategorie": "", "text": "etwas übertreiben, sich wild austoben, verrückt spielen (wie ein Pferd, das mit den Hinterbeinen über die Zugstränge [\"Schnur\"] seines Geschirrs ausschlägt, um zu galoppieren oder durchzugehen)"}]'::jsonb, ''),
