  ('in-schwulibus', 'in Schwulibus', '', '', '', '', 'in Schwulibus', '[{"kategorie": "wörtlich", "text": "\"in einem feuchtwarmen Notstand\" (vom niederdeutschen \"swūl\"=\"schwül\")"}, {"kategorie": "fig.", "text": "in einem Notstand, in Bedrängnis, in einer peinlichen Situation"}, {"kategorie": "", "text": "in Verlegenheit, in einer Zweickmühle, in der Bredouille"}]'::jsonb, 'in Schwulibus sei'),
