  ('i-zoi-ma-des-soeoewa', 'I zoi ma des sööwa!', '', '', '', '', 'Ich zahle mir das selber!', '[{"kategorie": "", "text": "Ich bezahle das aus eigener Tasche!  2. Das geht auf meine Rechnung!  3. Ich komme dafür selbst auf!"}]'::jsonb, ''),
  ('da-wiad-hod-soeoewa-kassiad', 'Da Wiad hod sööwa kassiad!', '', '', '', '', 'Der Wirt hat selber kassiert!', '[{"kategorie": "", "text": "Der Wirt persönlich hat kassiert!  2. Der Wirt hat höchstselbst kassiert!  3. Der Wirt selbst hat die Zahlung entgegengenommen!"}]'::jsonb, ''),
