  ('waunn-dea-huast-daunn-glaubsd-sei-soeoechbeischl-explodiat', 'Waunn dea huast, daunn glaubsd, sei Sööchbeischl explodiat!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der hustet, glaubst du, sein Selchbeuschel explodiert!', '[{"kategorie": "wörtlich", "text": "\"Wenn der hustet, glaubt man, seine Raucherlunge explodiert!\"  2. Wenn der hustet, denkst du, ihm fliegt gleich seine Raucherlunge um die Ohren!  3. Sein Husten klingt, als würde er gleich seine ganze Raucherlunge rauswürgen!"}]'::jsonb, ''),
  ('da-schbeck-haengd-schoo-seit-gestan-in-da-soeoech-und-riachd-healich', 'Da Schbeck hängd schoo seit gestan in da Sööch und riachd healich!', '', '', '', 'Wiener Fleischhauer-Slang', 'Der Speck hängt schon seit gestern in der Selche und riecht herrlich!', '[{"kategorie": "wörtlich", "text": "\"Der Speck hängt schon seit gestern in der Selchkammer und duftet herrlich!\"  2. Der Speck hängt schon seit gestern im Selchofen – und der Rauchduft zieht sich durchs ganze Haus!  3. Der Speck selcht seit gestern in der Räucherkammer vor sich hin – und es riecht einfach köstlich!"}]'::jsonb, ''),
  ('da-schbeck-haengd-scho-seit-gestan-im-soeoechoofn-und-riachd-healich', 'Da Schbeck hängd scho seit gestan im Sööchoofn und riachd healich!', '', '', '', 'Wiener Fleischhauer-Slang', 'Der Speck hängt schon seit gestern im Selchofen und riecht herrlich!', '[{"kategorie": "wörtlich", "text": "\"Der Speck hängt schon seit gestern im Selchofen und duftet herrlich!\"  2. Der Speck hängt schon seit gestern im Räucherofen – und der Rauchduft zieht sich durchs ganze Haus!  3. Der Speck selcht seit gestern in der Räucherkammer vor sich hin – und es riecht einfach köstlich!"}]'::jsonb, ''),
  ('muang-faung-ma-au-zum-soeoechn-da-schbeck-is-scho-featich-eigsuad', 'Muang faung ma au zum Sööchn - da Schbeck is scho featich eigsuad!', '', '', '', 'Wiener Fleischhauer-Slang', 'Morgen fangen wir an zu selchen – der Speck ist schon fertig eingesurt!', '[{"kategorie": "wörtlich", "text": "\"Morgen fangen wir an zu räuchern – der Speck ist schon fertig eingesalzen!\"  2. Morgen geht’s los mit dem Selchen – der Speck ist schon komplett eingesalzen!  3. Der Speck is fertig eingesurt – ab morgen kommt er in die [[Selche]]!"}]'::jsonb, ''),
  ('a-gsoeoechds-fleisch', 'a gsööchds Fleisch', '', '', '', 'Wiener Fleischhauer-Slang', 'ein geselchtes Fleisch', '[{"kategorie": "wörtlich", "text": "\"ein geräuchtertes Fleisch\" (vom mittelhochdeutschen [[selhen]]=\"räuchern\")"}, {"kategorie": "allg.", "text": "\"geräuchertes Schweinefleisch\", Räucherfleisch, Rauchfleisch, [[Selchfleisch]], [[Gsööchds]]"}]'::jsonb, 'Heit gibds a gsööchds Fleisch mit Sauakraut und Kneedl!'),
  ('heit-gibds-a-gsoeoechds-fleisch-mit-sauakraut-und-kneedl', 'Heit gibds a gsööchds Fleisch mit Sauakraut und Kneedl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Heute gibt''s geselchtes Fleisch mit Sauerkraut und Knödeln!', '[{"kategorie": "wörtlich", "text": "\"Heute gibt es [[Geselchtes]] mit Sauerkraut und Knödeln!\"  2. Heute kommt Geselchtes mit Kraut und Knödeln auf den Tisch!  3. Heute servieren wir geräuchertes Schweinefleisch mit Sauerkraut und Knödeln!"}]'::jsonb, 'a gsööchds Fleisch'),
  ('heit-gibds-a-soeoechfleisch-mit-sauakraut-und-kneedl', 'Heit gibds a Sööchfleisch mit Sauakraut und Kneedl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Heute gibt''s Selchfleisch mit Sauerkraut und Knödeln!', '[{"kategorie": "wörtlich", "text": "\"Heute gibt es [[Geselchtes]] mit Sauerkraut und Knödeln!\"  2. Heute kommt Geselchtes mit Kraut und Knödeln auf den Tisch!  3. Heute servieren wir geräuchertes Schweinefleisch mit Sauerkraut und Knödeln!"}]'::jsonb, ''),
  ('unsa-soeoecha-mochd-in-bestn-bauchschbeck-weit-und-breit', 'Unsa Sööcha mochd in bestn Bauchschbeck weit und breit!', '', '', '', 'Wiener Fleischhauer-Slang', 'Unser Selcher macht den besten Bauchspeck weit und breit!', '[{"kategorie": "wörtlich", "text": "\"Unser Selchfleischhauer macht den besten Bauchspeck weit und breit!\"  2. Unser [[Fleischselcher]] macht den schmackhaftesten Bauchspeck in der ganzen Gegend!  3. So guten Bauchspeck wie bei unserem Selcher findest du sonst nirgends!"}]'::jsonb, ''),
  ('a-fleischsoeoecha-vareedlds-fleisch-duach-suan-und-reichan', 'A Fleischsööcha vareedlds Fleisch duach Suan und Reichan!', '', '', '', 'Wiener Fleischhauer-Slang', 'Ein Fleischselcher veredelt s''Fleisch durch Suren und Räuchern!', '[{"kategorie": "wörtlich", "text": "\"Ein Fleischselcher veredelt das Fleisch durch Pökeln und Räuchern!\"  2. Ein Fleischselcher konserviert und aromatisiert Fleisch mit Salzlake und Rauch!  3. Der Fleischselcher verwandelt rohes Fleisch in würzige Delikatessen – durch gekonntes Pökeln und fein dosiertes Räuchern!"}]'::jsonb, ''),
  ('a-zoat-greichads-soeoechkarree-peafekt-fiad-breedljausn-oda-ois-woame-hauptspeis', 'A zoat greichads Sööchkarree – peafekt fiad Breedljausn oda ois woame Hauptspeis!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein zart geräuchertes Selchkarree – perfekt für die Brettljause oder als warme Hauptspeise!', '[{"kategorie": "wörtlich", "text": "\"Zart geräuchertes Schweinskarree – perfekt für die Brettljause oder als warme Hauptspeise!\"  2. Fein geräuchertes Selchkarree – ein Genuss als Brettljause oder als deftiges Hauptgericht!  3. Mildes Rauchfleisch vom Schwein – passt perfekt zur zünftigen Jause oder als wärmende Hauptspeise!"}]'::jsonb, ''),
  ('de-trangln-zoi-ma-se-soewa', 'De Trangln zoi ma se söwa!', '', '', '', '', 'Die Trankln zahlen wir sich selbst!', '[{"kategorie": "", "text": "Die Getränke zahlen wir uns selbst!  2. Die Getränke zahlen wir aus eigener Tasche!"}]'::jsonb, ''),
  ('tua-ned-giirassn', 'Tua ned giirassn!', '', '', '', '', 'Tu nicht gierassen!', '[{"kategorie": "", "text": "Sei nicht so geizig!  2. Sei nicht so neidisch!"}]'::jsonb, ''),
  ('i-loss-de-fraunkfuata-im-wossa-no-a-wengl-simman', 'I loss de Fraunkfuata im Wossa no a wengl simman!', '', '', '', '', 'Ich lasse die Frankfurter im Wasser noch ein wenig simmern!', '[{"kategorie": "", "text": "Ich lasse die Frankfurter Würstchen im Wasser noch ein wenig köcheln!  2. (Deutschland) Ich lasse die Wiener Würstchen im Wasser noch ein wenig garen!"}]'::jsonb, ''),
  ('ea-is-a-guada-lootsch-owa-hoid-a-bissal-a-simpal', 'Ea is a guada Lootsch, owa hoid a bissal a Simpal!', '', '', '', '', 'Er ist ein guter Latsch, aber halt ein bisschen ein Simperl!', '[{"kategorie": "wörtlich", "text": "\"Er ist ein guter Kerl, aber halt ein bisschen ein Simpel!\"  2. Er ist ein herzensguter Typ, nur halt nicht gerade der Hellste!  3. Er ist ein lieber Kerl, aber manchmal ein bisschen begriffsstutzig!"}]'::jsonb, 'a guada Lootsch'),
  ('ea-is-a-guada-lopp-owa-hoid-a-bissal-a-simpal', 'Ea is a guada Lopp, owa hoid a bissal a Simpal!', '', '', '', '', 'Er ist ein guter Lappen, aber halt ein bisschen ein Simperl!', '[{"kategorie": "wörtlich", "text": "\"Er ist ein guter Kerl, aber halt ein bisschen ein Simpel!\"  2. Er ist ein herzensguter Typ, nur halt nicht gerade der Hellste!  3. Er ist ein lieber Kerl, aber manchmal ein bisschen begriffsstutzig!"}]'::jsonb, 'a guada Lopp'),
